<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,toRaw,nextTick} from 'vue';
import {Plus,ChevronLeft,ChevronRight,Check,Clock3,Search,Pin,Flag,X,CalendarDays,ArrowUp,MoreHorizontal} from 'lucide-vue-next';
import {academicCache,schoolTerm} from '../composables/handan-academic';
import {schedule} from '../composables/schedule';
import {agendaView,taskView,taskSnapshot,tasksReady,tasksBusy,taskError,taskReminderStatus,initTasks,reloadTasks,changeTasks,enableTaskReminders} from '../composables/tasks';
import {beijingDay,validDay,shiftDay,buildAgenda,beijingTimestamp,validateTask,type CampusTask,type AgendaEvent,type CourseSeries} from '../domain/agenda';
import {selectTasks,taskSummary,taskOverdue,createTask,replanTask,TASK_TEMPLATES,type SmartList} from '../domain/tasks';
import {flatten,uid} from '../domain/schedule';
import {taskStore} from '../services/task-store';
import {saveFile} from '../services/files';
import type {Course} from '../domain/academic';
const emit=defineEmits<{course:[course:Course];navigate:[section:string]}>();
const editingExisting=ref(false);const titleInput=ref<HTMLInputElement>();let previousFocus:HTMLElement|null=null;
const now=ref(new Date()),message=ref(''),error=ref(''),draft=ref<CampusTask|null>(null),baseline=ref(''),discard=ref(false),removeIntent=ref(false),filters=ref(false),newStep=ref('');
const smartLists:[SmartList,string][]=[['today','今天'],['inbox','收件箱'],['planned','计划'],['due','即将截止'],['completed','已完成']];
const priorities=['无优先级','低优先级','中优先级','高优先级'];
const selectedDay=computed(()=>validDay(agendaView.date)?agendaView.date:beijingDay(now.value));
const series=computed<CourseSeries[]>(()=>{const all:CourseSeries[]=[];const school=schoolTerm.value?.data;if(school)all.push({semester:school.semester,courses:flatten(school.courses,school.semester.id,school.table),source:'school'});for(const semester of schedule.value.semesters){if(semester.id.startsWith('school-page-'))continue;const table=schedule.value.timeTables.find(t=>t.id===semester.timeTableId);all.push({semester,courses:flatten(schedule.value.courses,semester.id,table),source:'personal'})}return all});
const courses=computed(()=>[...new Set(series.value.flatMap(s=>s.courses.map(c=>c.name)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN')));
const courseOptions=computed(()=>[...new Set([...courses.value,...taskSnapshot.value.tasks.map(t=>t.course).filter(Boolean)])]);
const tasks=computed(()=>selectTasks(taskSnapshot.value.tasks,taskView,now.value));
const summary=computed(()=>taskSummary(taskSnapshot.value.tasks,now.value));
const groups=computed(()=>{if(!taskView.group)return [{name:'',tasks:tasks.value}];return [...new Set(tasks.value.map(t=>t.course))].map(name=>({name:name||'未关联课程',tasks:tasks.value.filter(t=>t.course===name)}))});
const agenda=computed(()=>buildAgenda(series.value,academicCache.value.exams.data||[],taskSnapshot.value.tasks,selectedDay.value,agendaView.range,now.value));
const timelineEvents=computed(()=>agenda.value.events.filter(e=>!e.completed&&(agendaView.filter==='all'||e.kind===agendaView.filter)));
const days=computed(()=>Array.from({length:agendaView.range},(_,i)=>{const date=shiftDay(selectedDay.value,i);return {date,events:timelineEvents.value.filter(e=>e.date===date)}}));
const nextEvent=computed(()=>timelineEvents.value.find(e=>e.startAt!==null&&e.startAt>=+now.value));
const courseStats=computed(()=>{const tasks=taskSnapshot.value.tasks.filter(t=>t.course===taskView.course);return {pending:tasks.filter(t=>!t.completed).length,completed:tasks.filter(t=>t.completed).length,due:taskSummary(tasks,now.value).due.length}});
const count=(view:SmartList)=>selectTasks(taskSnapshot.value.tasks,{...taskView,view,search:'',course:'',priority:-1},now.value).length;
function report(e:unknown){error.value=e instanceof Error?e.message:'操作未完成，请重试'}
async function quickAdd(){if(!taskView.quick.trim()||tasksBusy.value)return;error.value='';try{const task=createTask(taskView.quick.trim(),uid(),now.value);if(taskView.view==='today')task.plannedAt=beijingDay(now.value)+'T'+new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now.value);if(taskView.course)task.course=taskView.course;await changeTasks(()=>taskStore.upsert(task));taskView.quick='';if(taskView.view!=='today')taskView.view='inbox';message.value='任务已添加';}catch(e){report(e)}}
function edit(task?:CampusTask){editingExisting.value=!!task;previousFocus=document.activeElement as HTMLElement|null;draft.value=JSON.parse(JSON.stringify(task||{...createTask('新任务',uid(),now.value),title:''}));if(!task&&taskView.course)draft.value!.course=taskView.course;baseline.value=JSON.stringify(draft.value);agendaView.editor=true;newStep.value='';error.value='';discard.value=false;removeIntent.value=false;void nextTick(()=>titleInput.value?.focus())}
function trapFocus(e:KeyboardEvent){const form=e.currentTarget as HTMLElement;const items=[...form.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled])')].filter(el=>el.getClientRects().length);const target=e.shiftKey?items.at(-1):items[0];if((e.shiftKey&&document.activeElement===items[0])||(!e.shiftKey&&document.activeElement===items.at(-1))){e.preventDefault();target?.focus()}}
function closeEditor(){agendaView.editor=false;draft.value=null;discard.value=false;removeIntent.value=false;void nextTick(()=>previousFocus?.isConnected&&previousFocus.focus())}
function requestBack(){if(!agendaView.editor)return false;if(removeIntent.value){removeIntent.value=false;return true}if(discard.value){discard.value=false;return true}if(newStep.value.trim()||JSON.stringify(draft.value)!==baseline.value){discard.value=true;return true}closeEditor();return true}
defineExpose({requestBack});
async function save(){if(!draft.value||tasksBusy.value)return;try{if(newStep.value.trim())addStep();const task=validateTask({...toRaw(draft.value),plannedAt:draft.value.plannedAt||null,deadline:draft.value.deadline||null,updatedAt:new Date().toISOString()});await changeTasks(()=>taskStore.upsert(task,editingExisting.value?JSON.parse(baseline.value).updatedAt:undefined));closeEditor();message.value='待办已保存到本机'}catch(e){report(e)}}
async function complete(task:CampusTask){try{await changeTasks(()=>taskStore.complete(task.id,!task.completed));message.value=task.completed?'已恢复任务':'已完成，可在「已完成」中撤销'}catch(e){report(e)}}
async function remove(){if(!draft.value)return;try{const id=draft.value.id;await changeTasks(()=>taskStore.remove(id));closeEditor();message.value='任务已删除'}catch(e){report(e)}}
async function replan(task:CampusTask,offset:number){try{await changeTasks(()=>taskStore.change(s=>{const t=s.tasks.find(t=>t.id===task.id);if(!t)throw Error('任务已不存在');replanTask(t,shiftDay(beijingDay(now.value),offset),now.value)}));message.value='计划已调整，最终截止时间保持原样'}catch(e){report(e)}}
function addStep(){if(!draft.value||!newStep.value.trim())return;draft.value.steps!.push({id:uid(),title:newStep.value.trim(),completed:false});newStep.value=''}
function snoozeDraft(){if(!draft.value)return;const date=new Date(+now.value+10*60000);draft.value.snoozedUntil=beijingDay(date)+'T'+new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(date)}
function template(index:number){const t=TASK_TEMPLATES[index];edit();Object.assign(draft.value!,{title:t.title,durationMinutes:t.duration,steps:t.steps.map(title=>({id:uid(),title,completed:false}))})}
function repeatChanged(e:Event){if(!draft.value)return;const value=(e.target as HTMLSelectElement).value;draft.value.repeat=value==='none'?null:{kind:value as NonNullable<CampusTask['repeat']>['kind'],interval:1,weekdays:[1]}}
function toggleWeekday(day:number){const r=draft.value?.repeat;if(!r)return;r.weekdays=r.weekdays.includes(day)?r.weekdays.filter(d=>d!==day):[...r.weekdays,day]}
function addReminder(){if(!draft.value)return;draft.value.reminders!.push({id:uid(),anchor:draft.value.deadline?'deadline':'start',minutes:30})}
function selectEvent(e:AgendaEvent){if(e.taskId){const task=taskSnapshot.value.tasks.find(t=>t.id===e.taskId);if(task)edit(task)}else if(e.course)emit('course',e.course);else emit('navigate','exams')}
function moveDay(n:number){agendaView.date=shiftDay(selectedDay.value,n)}
function today(){agendaView.date=beijingDay(now.value)}
function week(){const day=new Date(selectedDay.value+'T12:00:00Z').getUTCDay()||7;agendaView.date=shiftDay(selectedDay.value,1-day);agendaView.range=7}
function dayLabel(day:string){return `${day===beijingDay(now.value)?'今天 · ':''}${day.slice(5).replace('-','月')}日 ${new Intl.DateTimeFormat('zh-CN',{weekday:'short',timeZone:'Asia/Shanghai'}).format(new Date(day+'T12:00:00+08:00'))}`}
function nowIndex(events:AgendaEvent[]){const i=events.findIndex(e=>e.startAt!==null&&e.startAt>+now.value);return i<0?events.length:i}
function eventState(e:AgendaEvent){if(e.startAt===null)return '时间待核对';if(e.kind==='task'&&e.source==='任务截止')return e.startAt<+now.value?'已逾期':'截止';return (e.endAt??e.startAt)<+now.value?'已结束':e.startAt<=+now.value?'进行中':'未开始'}
async function reminders(e:Event){try{await enableTaskReminders((e.target as HTMLInputElement).checked)}catch(e){report(e)}}
async function backup(){try{await saveFile('handan-tasks-'+beijingDay()+'.json',JSON.stringify(taskSnapshot.value,null,2));message.value='待办备份已生成'}catch(e){report(e)}}
async function restore(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>32*1024*1024)throw Error('备份超过32 MB');const data=JSON.parse(await file.text());await changeTasks(()=>taskStore.restore(data));message.value='备份已合并，已有任务和提醒开关保持原样'}catch(e){report(e)}finally{input.value=''}}
const timer=setInterval(()=>now.value=new Date(),30000);
onMounted(()=>{void initTasks().catch(()=>{})});onUnmounted(()=>{clearInterval(timer);agendaView.editor=false});
</script>
<template>
<section class="campus-agenda task-center" aria-label="统一日程">
 <div class="task-top"><div><h2>日程与待办</h2><p>{{summary.today.length}} 项今日任务 · {{summary.overdue.length}} 项逾期</p></div><button class="icon-button" aria-label="添加待办" :disabled="!tasksReady" @click="edit()"><Plus :size="21"/></button></div>
 <div class="task-mode" role="tablist" aria-label="待办与日程"><button role="tab" :aria-selected="taskView.mode==='list'" @click="taskView.mode='list'">任务清单</button><button role="tab" :aria-selected="taskView.mode==='timeline'" @click="taskView.mode='timeline'">日程时间轴</button></div>
 <p v-if="taskError||error" role="alert" class="task-message danger">{{error||taskError}} <button v-if="!tasksReady" @click="reloadTasks">重新读取</button></p><p v-if="message" role="status" class="task-message">{{message}}</p>
 <template v-if="taskView.mode==='list'">
  <div class="smart-lists" aria-label="智能清单"><button v-for="[id,label] in smartLists" :key="id" :aria-pressed="taskView.view===id" @click="taskView.view=id">{{label}}<small>{{count(id)}}</small></button></div>
  <div class="task-search"><Search :size="16"/><input v-model="taskView.search" type="search" aria-label="搜索任务" placeholder="搜索任务、课程或备注"/><button class="text-button" :aria-expanded="filters" @click="filters=!filters">筛选</button></div>
  <div v-if="filters" class="task-filters"><select v-model="taskView.course" aria-label="按课程筛选"><option value="">所有课程</option><option v-for="course in courseOptions" :key="course">{{course}}</option></select><select v-model="taskView.sort" aria-label="任务排序"><option value="smart">智能排序</option><option value="deadline">截止时间</option><option value="priority">重要程度</option><option value="title">标题</option></select><select v-model.number="taskView.priority" aria-label="优先级筛选"><option :value="-1">全部优先级</option><option v-for="(p,i) in priorities" :key="i" :value="i">{{p}}</option></select><label><input v-model="taskView.group" type="checkbox"/>按课程分组</label></div>
  <details class="task-templates"><summary>学生任务模板</summary><div><button v-for="(t,i) in TASK_TEMPLATES" :key="t.name" @click="template(i)">{{t.name}}</button></div></details>
  <div class="task-list-heading"><h3>{{smartLists.find(([id])=>id===taskView.view)?.[1]}}</h3><span>{{tasks.length}} 项<template v-if="taskView.course"> · {{courseStats.pending}} 待办 / {{courseStats.completed}} 完成 / {{courseStats.due}} 即将截止</template></span></div>
  <p v-if="taskView.view==='today'" class="task-hint">今日计划与已到期任务。可提前安排执行时间，提交截止保持独立。</p>
  <p v-if="taskView.view==='due'" class="task-hint">未来7天内的截止任务，包含逾期项。</p>
  <section v-for="group in groups" :key="group.name" class="task-group"><h4 v-if="group.name">{{group.name}} <small>{{group.tasks.length}} 项</small></h4>
   <article v-for="task in group.tasks" :key="task.id" class="task-row" :class="{done:task.completed,overdue:taskOverdue(task,now)}">
    <button class="task-check" :aria-label="(task.completed?'恢复待办 ':'完成待办 ')+task.title" :disabled="tasksBusy" @click="complete(task)"><Check v-if="task.completed" :size="15"/></button>
    <button class="task-copy" @click="edit(task)" @contextmenu.prevent="edit(task)"><strong><Pin v-if="task.pinned" :size="12"/><Flag v-if="task.priority" :size="12" :class="'priority-'+task.priority"/>{{task.title}}</strong><span v-if="task.course">{{task.course}}</span><span v-if="task.plannedAt"><Clock3 :size="11"/>计划 {{task.plannedAt.replace('T',' ')}} · {{task.durationMinutes}}分钟</span><span v-if="task.deadline" :class="{danger:taskOverdue(task,now)}">{{taskOverdue(task,now)?'已逾期 · ':'截止 '}}{{task.deadline.replace('T',' ')}}</span><span v-if="task.steps?.length" class="task-progress"><i :style="{width:90*task.steps.filter(s=>s.completed).length/task.steps.length+'px'}"/>{{task.steps.filter(s=>s.completed).length}}/{{task.steps.length}} 步骤<small v-if="task.repeat"> · 重复任务</small></span><span v-else-if="task.repeat">重复任务</span></button>
    <button class="icon-button task-more" :aria-label="'任务操作 '+task.title" @click="edit(task)"><MoreHorizontal :size="18"/></button>
    <div v-if="taskOverdue(task,now)" class="task-replan"><button @click="replan(task,0)">安排今天做</button><button @click="replan(task,1)">明天做</button><small>保留原截止</small></div>
   </article>
  </section>
  <div v-if="!tasks.length" class="task-empty"><Check :size="26"/><strong>{{taskView.search||taskView.course?'没有匹配任务':taskView.view==='inbox'?'先记下来，再安排':'这里暂时没有任务'}}</strong><p>在下方输入标题即可添加，也可使用学生任务模板。</p></div>
 </template>
 <template v-else>
  <div class="timeline-controls"><button class="icon-button" aria-label="前一天日程" @click="moveDay(-1)"><ChevronLeft :size="18"/></button><input v-model="agendaView.date" type="date" aria-label="日程日期"/><button class="icon-button" aria-label="后一天日程" @click="moveDay(1)"><ChevronRight :size="18"/></button><button class="text-button" @click="today">今天</button></div>
  <div class="timeline-options"><button :aria-pressed="agendaView.range===1" @click="agendaView.range=1">当天</button><button :aria-pressed="agendaView.range===7" @click="agendaView.range=7">未来7天</button><button @click="week">周视图</button><select v-model="agendaView.filter" aria-label="日程类型"><option value="all">全部安排</option><option value="course">课程</option><option value="exam">考试</option><option value="task">个人任务</option></select></div>
  <p v-if="!validDay(agendaView.date)" class="task-message">日期无效，暂显示今天。</p>
  <p v-if="summary.overdue.length" class="task-message danger"><button @click="taskView.mode='list';taskView.view='today'">{{summary.overdue.length}} 项任务逾期 · 重新规划</button></p>
  <p v-if="!schoolTerm?.data" class="task-hint">学校课表尚未同步，当前显示个人安排和已有考试缓存。</p><p v-if="academicCache.session==='expired'||schoolTerm?.error||academicCache.exams.error" class="task-hint">学校连接待更新，课程和考试显示上次缓存。</p>
  <p v-if="agenda.unknownExams" class="task-hint">{{agenda.unknownExams}} 条考试日期待核对，请查看考试安排原文。</p>
  <p v-if="nextEvent" class="task-next">即将开始 · {{nextEvent.title}} · {{nextEvent.time}}</p>
  <div v-for="day in days" :key="day.date" class="timeline-day"><h3>{{dayLabel(day.date)}}<small>{{day.events.length}} 项</small></h3>
   <template v-for="(e,index) in day.events" :key="e.id"><div v-if="day.date===beijingDay(now)&&index===nowIndex(day.events)" class="timeline-now">现在 {{new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'}).format(now)}}</div><article class="agenda-event timeline-event" :class="[e.kind,{deadline:e.source==='任务截止',current:e.startAt!==null&&e.startAt<=+now&&(e.endAt??0)>+now}]">
    <span class="timeline-dot"/><button class="timeline-copy" @click="selectEvent(e)"><small>{{e.time}} · {{eventState(e)}}</small><strong>{{e.title}}</strong><span>{{e.location||e.source}} · {{e.source}}{{e.kind==='task'?'':' · 只读'}}</span></button>
   </article></template><div v-if="day.date===beijingDay(now)&&nowIndex(day.events)===day.events.length" class="timeline-now">现在 {{new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'}).format(now)}}</div><p v-if="!day.events.length" class="task-hint">暂无已知安排</p></div>
  <p class="task-hint">任务执行时间和最终截止分别展示。学校课程日期依赖本机学期配置；个人任务不会修改学校安排。</p>
 </template>
 <details class="task-settings"><summary>提醒与待办备份</summary><label><span>开启待办系统提醒<small>{{taskReminderStatus}}</small></span><input type="checkbox" aria-label="开启待办提醒" :checked="taskSnapshot.notificationsEnabled" :disabled="!tasksReady||tasksBusy" @change="reminders"/></label><div><button :disabled="!tasksReady" @click="backup">导出待办备份</button><label class="task-import">恢复待办备份<input type="file" accept=".json,application/json" aria-label="恢复待办备份" @change="restore"/></label></div><p>兼容旧版备份，合并时保留已有任务。个人任务与学校账号独立保存；最多500项，提醒按最近30条续排。</p></details>
 <form class="task-quick" aria-label="快速添加任务" @submit.prevent="quickAdd"><Plus :size="18"/><input v-model="taskView.quick" aria-label="快速任务标题" maxlength="100" placeholder="添加任务，回车保存" :disabled="!tasksReady"/><button class="primary" aria-label="快速保存任务" :disabled="!tasksReady||tasksBusy||!taskView.quick.trim()"><ArrowUp :size="18"/></button></form>
 <Teleport to="body"><div v-if="agendaView.editor&&draft" class="task-sheet-backdrop" @click.self="requestBack"><form class="task-sheet" role="dialog" aria-modal="true" aria-label="任务详情" @keydown.tab="trapFocus" @submit.prevent="save"><header><button type="button" class="icon-button" aria-label="关闭任务详情" @click="requestBack"><X :size="20"/></button><strong>任务详情</strong><button class="primary" :disabled="tasksBusy">保存待办</button></header>
  <p v-if="error" role="alert" class="task-message danger">{{error}}</p>
  <div v-if="discard" class="task-confirm" role="alert"><strong>保留未保存的修改？</strong><button type="button" @click="discard=false">继续编辑</button><button type="button" @click="closeEditor">放弃修改</button></div>
  <label class="task-title-field"><span>标题</span><input ref="titleInput" v-model="draft.title" aria-label="待办标题" maxlength="100" required placeholder="准备做什么？"/></label>
  <div class="task-detail-grid"><label>计划开始（北京时间）<input v-model="draft.plannedAt" aria-label="任务计划开始" type="datetime-local"/></label><label>预计时长（分钟）<input v-model.number="draft.durationMinutes" aria-label="任务预计时长" type="number" min="5" max="1440" step="5"/></label><label>最终截止（北京时间）<input v-model="draft.deadline" aria-label="待办截止时间" type="datetime-local"/></label><label>优先级<select v-model.number="draft.priority" aria-label="任务优先级"><option v-for="(p,i) in priorities" :key="i" :value="i">{{p}}</option></select></label></div>
  <p class="task-hint" v-if="draft.plannedAt&&draft.deadline&&draft.plannedAt>draft.deadline">计划开始晚于截止时间，保存后仍保留原截止，请留意提交要求。</p>
  <label>关联课程<select v-model="draft.course" aria-label="关联课程"><option value="">不关联课程</option><option v-for="course in [...new Set([...courseOptions,draft.course].filter(Boolean))]" :key="course">{{course}}</option></select></label><label class="task-pin"><input v-model="draft.pinned" type="checkbox"/>置顶任务</label>
  <section class="task-steps"><h3>步骤 <small>{{draft.steps?.filter(s=>s.completed).length}}/{{draft.steps?.length}}</small></h3><div v-for="(step,i) in draft.steps" :key="step.id"><input v-model="step.completed" type="checkbox" :aria-label="'完成步骤 '+step.title"/><input v-model="step.title" :aria-label="'步骤标题 '+(i+1)" maxlength="100"/><button type="button" :aria-label="'删除步骤 '+(i+1)" @click="draft.steps!.splice(i,1)"><X :size="14"/></button></div><div><input v-model="newStep" aria-label="新步骤标题" maxlength="100" placeholder="拆成更容易开始的小步骤" @keydown.enter.prevent="addStep"/><button type="button" :disabled="(draft.steps?.length??0)>=50" @click="addStep">添加步骤</button></div></section>
  <label>重复<select :value="draft.repeat?.kind||'none'" aria-label="任务重复规则" @change="repeatChanged"><option value="none">不重复</option><option value="daily">每天</option><option value="weekdays">工作日（周一至周五）</option><option value="weekly">每周</option><option value="days">指定星期</option><option value="interval">自定义天数</option></select></label><label v-if="draft.repeat?.kind==='interval'">每隔几天<input v-model.number="draft.repeat.interval" type="number" min="1" max="365" aria-label="重复间隔天数"/></label><div v-if="draft.repeat?.kind==='days'" class="task-weekdays"><button v-for="(d,i) in ['一','二','三','四','五','六','日']" :key="d" type="button" :aria-pressed="draft.repeat.weekdays.includes(i+1)" @click="toggleWeekday(i+1)">周{{d}}</button></div><p v-if="draft.repeat" class="task-hint">完成后创建下一次未来任务，保留本次记录。工作日不含法定节假日调整；重复以计划开始为基准，没有计划时以截止为基准。</p>
  <section class="task-reminders"><h3>多次提醒 <button type="button" :disabled="(draft.reminders?.length??0)>=5" @click="addReminder">添加提醒</button></h3><div v-for="(r,i) in draft.reminders" :key="r.id"><select v-model="r.anchor" :aria-label="'提醒依据 '+(i+1)"><option value="start">计划开始前</option><option value="deadline">最终截止前</option><option value="absolute">指定时间</option></select><input v-if="r.anchor==='absolute'" v-model="r.at" type="datetime-local" :aria-label="'提醒时间 '+(i+1)"/><input v-else v-model.number="r.minutes" type="number" min="0" max="525600" :aria-label="'提前分钟 '+(i+1)"/><button type="button" :aria-label="'删除提醒 '+(i+1)" @click="draft.reminders!.splice(i,1)"><X :size="14"/></button></div><p class="task-hint">相对提醒填写提前分钟数，0为当时提醒。没有对应时间的提醒暂不调度；系统开关需主动开启。通知可完成任务或稍后10分钟提醒。</p></section>
  <div class="task-snooze"><button type="button" @click="snoozeDraft">10分钟后提醒</button><small v-if="draft.snoozedUntil">{{draft.snoozedUntil.replace('T',' ')}} · 保存后生效 <button type="button" @click="draft.snoozedUntil=null">取消稍后提醒</button></small><p class="task-hint">需开启下方系统提醒。此操作保留计划时间和截止时间。</p></div>
  <label>备注<textarea v-model="draft.notes" aria-label="待办备注" maxlength="1000" rows="3"/></label>
  <div v-if="taskSnapshot.tasks.some(t=>t.id===draft!.id)" class="task-detail-actions"><button type="button" @click="draft=replanTask(draft,beijingDay(now),now)">今天做</button><button type="button" @click="draft=replanTask(draft,shiftDay(beijingDay(now),1),now)">明天做</button><button type="button" class="danger" @click="removeIntent=true">删除任务</button></div><div v-if="removeIntent" class="task-confirm"><span>删除这项任务？</span><button type="button" @click="removeIntent=false">取消</button><button type="button" class="danger" :disabled="tasksBusy" @click="remove">确认删除</button></div>
 </form></div></Teleport>
</section>
</template>
